// Печатный сценарий проверки прототипа на пяти людях.
const path = require("node:path"), fs = require("node:fs");
const { launch, sleep } = require("./cdp");
const OUT = path.resolve(__dirname, "../../..", "Сценарий_проверки_прототипа.pdf");
const rows = [1,2,3,4,5].map(n=>`<tr><td>${n}</td><td></td><td></td><td></td><td></td><td></td></tr>`).join("");
const html = `<!doctype html><html lang="ru"><meta charset="utf-8"><title>Сценарий проверки прототипа PrintNow</title><style>
@page{size:A4;margin:16mm 16mm}body{font:11pt/1.35 Arial,sans-serif;color:#1F2A30;margin:0}
h1{font-size:18pt;margin:0 0 4pt}h2{font-size:12.5pt;margin:12pt 0 4pt}p{margin:0 0 5pt}ol,ul{margin:0 0 6pt;padding-left:16pt}li{margin-bottom:3pt}
.say{background:#F2EEE6;padding:7pt 9pt;border-radius:5pt;margin-bottom:6pt}
table{width:100%;border-collapse:collapse;font-size:9.5pt;table-layout:fixed}th{background:#F2EEE6;text-align:left}th,td{border:.6pt solid #8A8F8C;padding:4pt;vertical-align:top}td{height:62pt}
.brk{break-before:page}</style>
<h1>Сценарий проверки прототипа PrintNow</h1><p>Для раздела 3.5 и требования NFR-04. Время: около 10–15 минут на человека.</p>
<h2>Подготовка</h2><ol><li>Нужны 5 человек не из команды. Лучше 4 клиента копицентра и 1 сотрудник копицентра, если получится договориться.</li><li>Откройте <b>printnow/prototype/index.html</b> в Chrome (или опубликованную ссылку на прототип).</li><li>Перед каждым участником нажимайте вверху <b>«Сбросить данные»</b>. Приготовьте секундомер и этот лист.</li></ol>
<h2>Что сказать участнику</h2><div class="say">«Мы проверяем не вас, а сервис. Если что-то непонятно, значит, плохо сделан сервис. Пожалуйста, думайте вслух. Я не буду подсказывать. Оплата здесь не настоящая, деньги не списываются».</div>
<p><b>Во время задач не подсказывайте</b>, даже если человек застрял: запишите, где и почему. Подскажите, только если он сдаётся, и отметьте это.</p>
<h2>Задачи</h2><ol>
<li><b>Первый заказ, запустите секундомер.</b> «Вам нужно напечатать курсовую на 24 страницах с переплётом. Оформите и оплатите заказ». Для примера файла есть ссылка «Взять пример». Остановите секундомер, когда появится код. <i>Норма: не более 3 минут и 5 шагов.</i></li>
<li><b>Цена.</b> «Сколько стоит заказ? Из чего складывается сумма?» Заметил ли человек сбор 1 000 сум сам?</li>
<li><b>Получение.</b> «Что вы скажете на точке, чтобы забрать заказ? К какому времени он будет готов?»</li>
<li><b>Повтор.</b> «Закажите то же самое ещё раз». Нашёл ли «Мои заказы» и «Повторить»?</li>
<li><b>Только для сотрудника копицентра.</b> «Вы оператор: возьмите заказ в печать, отметьте готовность, выдайте его по коду». Откройте роль «Оператор печати».</li></ol>
<h2>Вопросы после задач</h2><ol><li>Где было непонятно?</li><li>Заплатили бы вы 1 000 сум сверх цены точки, чтобы не стоять в очереди? Почему?</li><li>Заплатили бы вы онлайн заранее или предпочли бы на кассе?</li></ol>
<h2 class="brk">Бланк результатов</h2><p>Дата проверки: ______________. Проводил(а): ______________. Запишите, кто участник без фамилии: например, «студент, 2 курс».</p>
<table><colgroup><col style="width:5%"><col style="width:17%"><col style="width:11%"><col style="width:29%"><col style="width:19%"><col style="width:19%"></colgroup><thead><tr><th>№</th><th>Кто</th><th>Время заказа (м:сс)</th><th>Где споткнулся(ась), что сказал(а)</th><th>Заметил(а) сбор? Готов(а) платить?</th><th>Что исправить</th></tr></thead><tbody>${rows}</tbody></table>
<h2>После проверки</h2><p>Пришлите заметки в чат с Claude: сфотографируйте бланк или перепишите его текстом. Прототип исправляется по результатам, раздел 3.5 и таблица 3.9 заполняются реальными данными, затем PDF собирается заново. <b>Придумывать результаты нельзя:</b> на защите могут спросить любого из пяти участников.</p></html>`;
(async()=>{const f=path.join(process.env.TMPDIR||"/tmp","pn_sheet.html");fs.writeFileSync(f,html);const c=await launch();await c.open("file://"+f);await sleep(300);await c.pdf(OUT,{});await c.close();console.log(OUT);})();
